[TestClass][DoNotParallelize]public sealed class HomeR55RefreshTests
{
 static string Root(){var root=Environment.GetEnvironmentVariable("KITAO_HOME_R55_ROOT")??Path.Combine(Path.GetTempPath(),"home-r55-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);return root;}
 static void Layout(FrameworkElement view,int width=1366){view.Measure(new Size(width,width==1920?1080:768));view.Arrange(new Rect(0,0,width,width==1920?1080:768));view.UpdateLayout();}
 static IEnumerable<T> Find<T>(DependencyObject d)where T:DependencyObject{if(d is T x)yield return x;for(int i=0;i<VisualTreeHelper.GetChildrenCount(d);i++)foreach(var child in Find<T>(VisualTreeHelper.GetChild(d,i)))yield return child;}
 static void Click(Button b)=>b.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));
 static async Task<ReferenceColorWorkspaceViewModel> Workspace(){EnsureTestApplication();var vm=new ReferenceColorWorkspaceViewModel(new CompanyViewingMeasurementsTests.Dialogs());for(int n=0;n<3;n++){var w=n==1?120:240;var h=n==1?240:160;var rgb=new byte[w*h*3];for(int y=0;y<h;y++)for(int x=0;x<w;x++){var i=(y*w+x)*3;rgb[i]=(byte)(x%251);rgb[i+1]=(byte)((y+n*40)%251);rgb[i+2]=(byte)((x+y)%251);}var bitmap=BitmapSource.Create(w,h,96,96,PixelFormats.Rgb24,null,rgb,w*3);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(bitmap));var path=Path.Combine(Root(),$"owned-r55-{n}.png");using(var f=File.Create(path))e.Save(f);await vm.LoadTargetAsync(path);await vm.CreateR53VariantAsync(true);vm.ActiveTarget!.IsSelected=true;}vm.PinSelectedViewingVariants();await vm.PrepareViewingTableAsync();return vm;}
 [TestMethod]public Task IndependentLayersKeepPhotoGeometryAndSelectionOutOfLabel()=>RunSta(async()=>{
  new ViewingPreferences(ReduceMotion:true,Sound:false).Save();using var vm=await Workspace();var table=new StudioViewingTableView(vm);Layout(table);foreach(var width in new[]{1366,1920,800,1366}){Layout(table,width);var entries=Find<Button>(table).Where(b=>System.Windows.Automation.AutomationProperties.GetName(b).EndsWith("展开")).ToArray();Assert.AreEqual(2,entries.Length);foreach(var entry in entries){Assert.AreEqual(22d,entry.ActualWidth);Assert.AreEqual(76d,entry.ActualHeight);Assert.AreEqual("▸\n展\n开",((TextBlock)entry.Content).Text);}}await table.RefreshAsync();Layout(table);table.SelectForTest(vm.ViewingFrames[1]);Layout(table);
  foreach(var card in table.CardsForTest){Assert.AreEqual(0,card.BorderThickness.Left);Assert.IsNull(card.Effect);Assert.AreEqual(1d,card.Opacity);var panel=(Grid)card.Child;var photo=panel.Children.OfType<Image>().Single();var marks=panel.Children.OfType<Grid>().Single();var label=panel.Children.OfType<TextBlock>().Single();Assert.AreEqual(1,Grid.GetRow(label));Assert.AreEqual(photo.ActualWidth,marks.ActualWidth,.01);Assert.AreEqual(photo.ActualHeight,marks.ActualHeight,.01);Assert.AreEqual(((ViewingTableItem)card.Tag).VariantId==table.SelectedVariant?Visibility.Visible:Visibility.Collapsed,marks.Children.OfType<Border>().Single().Visibility);Assert.IsFalse(marks.IsHitTestVisible);}
  var first=vm.ViewingTable.Items.First();table.BeginGestureForTest(first);vm.SetViewingPlacement(first.TargetId,first.VariantId,100,80,1,0);foreach(var card in table.CardsForTest)Assert.AreEqual(Visibility.Collapsed,Find<Border>(card).Single(b=>b.Name=="PhotoSelection").Visibility);table.EndGestureForTest(true);table.Close();new ViewingPreferences().Save();
 });
 [TestMethod]public Task RefreshRetainsFixedRowsAndInfoControlsAndOnlyNotifiesNewFailures()=>RunSta(async()=>{
  new ViewingPreferences(LeftOpen:true,RightOpen:true,ReduceMotion:true,Sound:false).Save();using var vm=await Workspace();var table=new StudioViewingTableView(vm);Layout(table);var builds=table.FixedListRebuildCount;var chrome=table.ChromeContentBuildCount;var firstRows=Find<Button>(table).Where(b=>b.Tag is ViewingTableItem).ToArray();int failures=0,frames=0;vm.PropertyChanged+=(_,e)=>{if(e.PropertyName==nameof(vm.ViewingFailures))failures++;if(e.PropertyName==nameof(vm.ViewingFrames))frames++;};await table.RefreshAsync();Layout(table);Assert.AreEqual(0,failures);Assert.AreEqual(4,frames);Assert.AreEqual(builds,table.FixedListRebuildCount);Assert.AreEqual(chrome,table.ChromeContentBuildCount);CollectionAssert.AreEqual(firstRows,Find<Button>(table).Where(b=>b.Tag is ViewingTableItem).ToArray());var images=vm.ViewingFrames.ToDictionary(f=>f.Item.VariantId,f=>f.Image);var bad=vm.ViewingTable.Items[0].VariantId;vm.ViewingRenderOverride=(i,_,_)=>i.VariantId==bad?Task.FromException<BitmapSource>(new IOException("owned explicit failure")):Task.FromResult(images[i.VariantId]);await table.RefreshAsync();Assert.AreEqual(1,failures);Assert.AreEqual(1,vm.ViewingFailures.Count);Layout(table);var retry=Find<Button>(table).Single(b=>b.Content as string=="重试失败项");var feedback=Find<TextBlock>(table).Single(t=>t.Text==table.VisibleStatus);var bottom=feedback.TransformToAncestor(table).Transform(new Point(0,feedback.ActualHeight));var top=retry.TransformToAncestor(table).Transform(new Point(0,0));Assert.IsTrue(top.Y>=bottom.Y,"Failure actions must not overlap persistent status");Assert.AreEqual(builds,table.FixedListRebuildCount);table.FixedFilter=1;Assert.AreEqual(1,Find<Button>(table).Count(b=>b.Tag is ViewingTableItem));table.Close();new ViewingPreferences().Save();
 });
 [TestMethod]public Task FilmNumericEntryResetAndTaskDisabledStateUseActualSettings()=>RunSta(async()=>{
  new ViewingPreferences(ReduceMotion:true,Sound:false).Save();using var vm=await Workspace();var table=new StudioViewingTableView(vm);Layout(table);await table.RefreshAsync();table.SelectForTest(vm.ViewingFrames[0]);table.OpenFilmSidebarForTest();await table.PreflightForTest();Layout(table);var choice=Find<ComboBox>(table).Single(c=>c.ItemsSource==PixelTartFilmProfiles.All);Assert.IsTrue(choice.ActualHeight>=28);table.AmountNumberForTest.Text="42";table.AmountNumberForTest.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice,0,table.AmountNumberForTest,table){RoutedEvent=Keyboard.LostKeyboardFocusEvent});Assert.AreEqual(42d,table.AmountForTest.Value);table.GrainForTest.Value=17;Assert.AreEqual("17",table.GrainNumberForTest.Text);Click(Find<Button>(table).Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="胶片强度复位"));Assert.AreEqual(100d,table.AmountForTest.Value);Click(Find<Button>(table).Single(b=>System.Windows.Automation.AutomationProperties.GetName(b)=="胶片颗粒复位"));Assert.AreEqual(0d,table.GrainForTest.Value);table.AmountForTest.Value=63;table.GrainForTest.Value=11;
  var started=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var finish=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);vm.ViewingFilmBeforeCommit=async t=>{started.TrySetResult();await finish.Task;};Click(table.GenerateButton);await started.Task;Assert.IsFalse(table.AmountForTest.IsEnabled);Assert.IsFalse(table.GrainNumberForTest.IsEnabled);Assert.IsTrue(table.FilmCancelButton.IsEnabled);StringAssert.Contains(table.FilmPanelStatus,vm.FilmTaskStatus);foreach(var width in new[]{1366,1920}){Layout(table,width);CaptureTask("running",width);}finish.SetResult();await table.GenerateWork;foreach(var width in new[]{1366,1920}){Layout(table,width);CaptureTask("success",width);}var result=vm.Targets.SelectMany(t=>t.EditVersions).Single(v=>v.Id==vm.LastViewingFilmResult);Assert.AreEqual(63d,result.Film!.ProfileAmount);Assert.AreEqual(11d,result.Film.GrainAmount);Assert.IsTrue(table.AmountForTest.IsEnabled);table.Close();new ViewingPreferences().Save();
  void CaptureTask(string state,int width){var root=Path.Combine(Root(),"production-task");Directory.CreateDirectory(root);var b=new RenderTargetBitmap((int)table.ActualWidth,(int)table.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(table);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using var f=File.Create(Path.Combine(root,$"OFFSCREEN-task-{state}-{width}.png"));e.Save(f);}
 });
 [TestMethod]public Task GeometryFastPathKeepsFrozenReferencesUndoAndFullBoundaryRejection()=>RunSta(async()=>{
  using var vm=await Workspace();var before=JsonSerializer.Serialize(vm.ViewingTable);var item=vm.ViewingTable.Items[0];var untouched=vm.ViewingTable.Items[1];vm.BeginViewingGesture();for(int n=0;n<40;n++)vm.SetViewingPlacement(item.TargetId,item.VariantId,80+n,50,1.2,30);vm.CommitViewingGesture();Assert.AreSame(item.FrozenVariant,vm.ViewingTable.Items[0].FrozenVariant);Assert.AreSame(untouched,vm.ViewingTable.Items[1]);vm.UndoViewing();Assert.AreEqual(before,JsonSerializer.Serialize(vm.ViewingTable));vm.RedoViewing();Assert.AreEqual(119d,vm.ViewingTable.Items[0].X);Assert.ThrowsExactly<InvalidDataException>(()=>vm.SetViewingPlacement(item.TargetId,item.VariantId,double.NaN,50,1,0));Assert.ThrowsExactly<InvalidDataException>(()=>vm.Layout=vm.Layout with{ViewingTable=vm.ViewingTable with{Items=new[]{item with{RecipeHash=new string('0',64)}}}});Assert.ThrowsExactly<InvalidDataException>(()=>(vm.ViewingTable with{Version=999}).Validate());
 });
 [TestMethod]public Task OwnedPortraitLoupeAndSlideshowProductionScreens()=>RunSta(async()=>{
  new ViewingPreferences(ReduceMotion:true,Sound:false).Save();using var vm=await Workspace();var table=new StudioViewingTableView(vm);await table.RefreshAsync();var root=Path.Combine(Root(),"production-extra");Directory.CreateDirectory(root);var metrics=new List<object>();foreach(var width in new[]{1366,1920}){Layout(table,width);table.SelectForTest(vm.ViewingFrames[1]);await table.LoupeForHost();Layout(table,width);Capture("portrait-loupe");table.HandleShortcut(Key.A,ModifierKeys.None);table.DetailRenderer=(i,_,_)=>Task.FromResult(vm.ViewingFrames.Single(f=>f.Item.VariantId==i.VariantId).Image);await table.StartSlideshowForTest();table.PauseSlideshowForTest();Layout(table,width);Capture("slide-paused");metrics.Add(new{width,table.ActualWidth,table.ActualHeight,table.SlidePhase,table.SlideshowPaused});table.ExitDetailForHost();}File.WriteAllText(Path.Combine(root,"METRICS.json"),JsonSerializer.Serialize(metrics));table.Close();new ViewingPreferences().Save();
  void Capture(string state){var image=new RenderTargetBitmap((int)table.ActualWidth,(int)table.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(table);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(image));using var f=File.Create(Path.Combine(root,$"OFFSCREEN-owned-{state}-{(int)table.ActualWidth}.png"));e.Save(f);}
 });
 // This test deliberately uses only pre-existing product APIs, so the SAME fixture can bind both baseline and release DLLs.
 [TestMethod]public Task StableOwnedInputPixelAndExportABFixture()=>RunSta(async()=>{
  using var vm=await Workspace();var records=new List<object>();foreach(var frame in vm.ViewingFrames){var item=frame.Item;var target=vm.Targets.Single(t=>t.Id==item.TargetId);var v=item.FrozenVariant;var output=await vm.Editor.ProcessForExportAsync(target.Path,v.Look,v.Film,CancellationToken.None,v.Stack);static string Hash(BitmapSource x){var b=new FormatConvertedBitmap(x,PixelFormats.Bgra32,null,0);var bytes=new byte[b.PixelWidth*b.PixelHeight*4];b.CopyPixels(bytes,b.PixelWidth*4,0);return Convert.ToHexString(SHA256.HashData(bytes));}records.Add(new{source=Path.GetFileName(target.Path),sourceHash=target.SourceHash,proxyPixels=Hash(frame.Image),exportPixels=Hash(output)});}await File.WriteAllTextAsync(Path.Combine(Root(),"OWNED_PIXEL_AB.json"),JsonSerializer.Serialize(records,new JsonSerializerOptions{WriteIndented=true}));
 });
}



